wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        use crate::aap::caps::state_rw;

        // Mark each considered item as seen in the read-write 'seen' store.
        // Count the ones that were not already present, so `recorded` is the
        // number of items this run newly recorded. For a u32 this is >= 0 by
        // construction, satisfying the node's `ensures recorded >= 0`.
        let mut recorded: u32 = 0;
        for id in &published.considered {
            if state_rw::get(id).is_none() {
                state_rw::put(id, &published.date);
                recorded = recorded.saturating_add(1);
            }
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
